    " */\nconst CW = 12, CH = 24;\n\nconst tctx "
    "= ui.text.getContext(\"2d\", { alpha: fals"
    "e });\nconst pctx = ui.pix.getContext(\"2d"
    "\", { alpha: false });\n\n/* ---- the text "
    "screen ---------------------------------"
    "----------------- */\n\nfunction resizeTex"
    "t() {\n  ui.text.width = st.cols * CW;\n  "
    "ui.text.height = st.rows * CH;\n  st.cell"
    "s = new Uint16Array(st.cols * st.rows).f"
    "ill(0x0720);\n  tctx.textBaseline = \"top\""
    ";\n  tctx.font = `${CH - 4}px ui-monospac"
    "e, \"SF Mono\", Menlo, Consolas, monospace"
    "`;\n  paintText();\n}\n\nfunction paintCell("
    "x, y) {\n  const v = st.cells[y * st.cols"
    " + x];\n  const ch = v & 0xff, attr = v >"
    "> 8;\n  const px = x * CW, py = y * CH;\n\n"
    "  tctx.fillStyle = CGA[(attr >> 4) & 7];"
    "\n  tctx.fillRect(px, py, CW, CH);\n\n  con"
    "st caret = st.cur.on && st.cur.x === x &"
    "& st.cur.y === y;\n  if (caret) {\n    tct"
    "x.fillStyle = CGA[attr & 15];\n    tctx.f"
    "illRect(px, py + CH - 3, CW, 2);\n  }\n  i"
    "f (ch !== 32 && ch !== 0) {\n    tctx.fil"
    "lStyle = CGA[attr & 15];\n    tctx.fillTe"
    "xt(CP437[ch], px + 1, py + 2);\n  }\n}\n\nfu"
    "nction paintText() {\n  for (let y = 0; y"
    " < st.rows; y++) {\n    for (let x = 0; x"
    " < st.cols; x++) paintCell(x, y);\n  }\n}\n"
    "\n/* One repaint per animation frame howe"
    "ver many rows arrived, because a screen\n"
    " * clearing is twenty-five messages and "
    "twenty-five full repaints is a phone\n * "
    "that stutters on a `cls`. */\nfunction sc"
    "hedulePaint(rows) {\n  if (!st.pending) {"
    "\n    st.pending = true;\n    requestAnima"
    "tionFrame(() => { st.pending = false; fl"
    "ushRows(); });\n  }\n  for (const r of row"
    "s) st.dirtyRows.add(r);\n}\n\nfunction flus"
    "hRows() {\n  for (const y of st.dirtyRows"
    ") {\n    if (y >= st.rows) continue;\n    "
    "for (let x = 0; x < st.cols; x++) paintC"
    "ell(x, y);\n  }\n  st.dirtyRows.clear();\n}"
    "\n\n/*\n * The splash goes on the first thi"
    "ng that arrives, whatever it is - not in"
    "side\n * the mode switch below, which ret"
    "urns early when the mode has not changed"
    " and\n * so never ran at all for a board "
    "that started in text and stayed there.\n "
    "*/\nfunction showText() {\n  ui.splash.hid"
    "den = true;\n  if (st.mode === \"text\") re"
    "turn;\n  st.mode = \"text\";\n  ui.pix.hidde"
    "n = true;\n  ui.text.hidden = false;\n}\n\n/"
    "* ---- the picture ---------------------"
    "--------------------------------- */\n\nfu"
    "nction showPixels() {\n  ui.splash.hidden"
    " = true;\n  if (st.mode === \"pix\") return"
    ";\n  st.mode = \"pix\";\n  ui.text.hidden = "
    "true;\n  ui.pix.hidden = false;\n}\n\nfuncti"
    "on resizePix(w, h) {\n  if (ui.pix.width "
    "=== w && ui.pix.height === h) return;\n  "
    "ui.pix.width = w;\n  ui.pix.height = h;\n "
    " pctx.fillStyle = \"#000\";\n  pctx.fillRec"
    "t(0, 0, w, h);\n}\n\n/*\n * PackBits over 16"
    "-bit pixels, and over bytes.  Mirrors pa"
    "ck16 / pack8 in\n * apps/common/pixband/a"
    "g_pixband.c: a control byte, then either"
    " that many\n * literals or that many copi"
    "es of one.\n */\nfunction unpack16(v, at, "
    "end, out, n) {\n  let o = 0;\n  while (at "
    "< end) {\n    const ctl = v.getUint8(at++"
    ");\n    if (ctl & 0x80) {\n      const run"
    " = (ctl - 0x80) + 2;\n      const px = v."
    "getUint16(at, true); at += 2;\n      if ("
    "o + run > n) return false;\n      for (le"
    "t k = 0; k < run; k++) out[o++] = px;\n  "
    "  } else {\n      const lit = ctl + 1;\n  "
    "    if (o + lit > n) return false;\n     "
    " for (let k = 0; k < lit; k++) { out[o++"
    "] = v.getUint16(at, true); at += 2; }\n  "
    "  }\n  }\n  return o === n;\n}\n\nfunction un"
    "pack8(v, at, end, out, n) {\n  let o = 0;"
    "\n  while (at < end) {\n    const ctl = v."
    "getUint8(at++);\n    if (ctl & 0x80) {\n  "
    "    const run = (ctl - 0x80) + 2;\n      "
    "const b = v.getUint8(at++);\n      if (o "
    "+ run > n) return false;\n      for (let "
    "k = 0; k < run; k++) out[o++] = b;\n    }"
    " else {\n      const lit = ctl + 1;\n     "
    " if (o + lit > n) return false;\n      fo"
    "r (let k = 0; k < lit; k++) out[o++] = v"
    ".getUint8(at++);\n    }\n  }\n  return o =="
    "= n;\n}\n\nfunction band(op, v, at, end) {\n"
    "  const x = v.getUint16(at, true), y = v"
    ".getUint16(at + 2, true);\n  const w = v."
    "getUint16(at + 4, true), h = v.getUint16"
    "(at + 6, true);\n  at += 8;\n\n  const n = "
    "w * h;\n  if (n === 0 || n > 1 << 20) ret"
    "urn;\n  const px = new Uint16Array(n);\n\n "
    " if (op === OP_RAW) {\n    if (end - at !"
    "== n * 2) return;\n    for (let i = 0; i "
    "< n; i++) px[i] = v.getUint16(at + i * 2"
    ", true);\n  } else if (op === OP_PACK) {\n"
    "    if (!unpack16(v, at, end, px, n)) re"
    "turn;\n  } else {\n    const bpp = v.getUi"
    "nt8(at), ncol = v.getUint8(at + 1) + 1;\n"
    "    at += 2;\n    const pal = new Uint16A"
    "rray(ncol);\n    for (let i = 0; i < ncol"
    "; i++) { pal[i] = v.getUint16(at, true);"
    " at += 2; }\n    const bytes = bpp === 4 "
    "? ((n + 1) >> 1) : n;\n    const raw = ne"
    "w Uint8Array(bytes);\n    if (!unpack8(v,"
    " at, end, raw, bytes)) return;\n    for ("
    "let i = 0; i < n; i++) {\n      const idx"
    " = bpp === 4\n        ? ((i & 1) ? (raw[i"
    " >> 1] >> 4) : (raw[i >> 1] & 15))\n     "
    "   : raw[i];\n      if (idx >= ncol) retu"
    "rn;\n      px[i] = pal[idx];\n    }\n  }\n\n "
    " /* RGB565 to the canvas's RGBA, with th"
    "e low bits replicated into the high\n   *"
    " ones so that full white stays full whit"
    "e instead of landing at 248. */\n  const "
    "img = pctx.createImageData(w, h);\n  cons"
    "t d = img.data;\n  for (let i = 0, j = 0;"
    " i < n; i++) {\n    const c = px[i];\n    "
    "const r = (c >> 11) & 31, g = (c >> 5) &"
    " 63, b = c & 31;\n    d[j++] = (r << 3) |"
    " (r >> 2);\n    d[j++] = (g << 2) | (g >>"
    " 4);\n    d[j++] = (b << 3) | (b >> 2);\n "
    "   d[j++] = 255;\n  }\n  pctx.putImageData"
    "(img, x, y);\n  showPixels();\n}\n\n/* ---- "
    "the connection -------------------------"
    "-------------------------- */\n\n/*\n * The"
    " password is kept per board, so one phon"
    "e can hold several without being\n * aske"
    "d each time, and dropped the moment the "
    "board says it was wrong.  In the\n * brow"
    "ser's own storage: it never leaves this "
    "device, and what crosses the wire\n * is "
    "a digest of it and a nonce, never the pa"
    "ssword.\n */\nconst PW_KEY = \"argon.pw.\" +"
    " location.host;\n\nfunction storedPassword"
    "() {\n  try { return localStorage.getItem"
    "(PW_KEY) || \"\"; } catch (e) { return \"\";"
    " }\n}\n\nfunction rememberPassword(pw) {\n  "
    "try { if (pw) localStorage.setItem(PW_KE"
    "Y, pw); else localStorage.removeItem(PW_"
    "KEY); }\n  catch (e) { /* a private windo"
    "w; ask again next time */ }\n}\n\nfunction "
    "answerChallenge(nonce, pw) {\n  const byt"
    "es = new TextEncoder().encode(pw);\n  con"
    "st buf = new Uint8Array(nonce.length + b"
    "ytes.length);\n  buf.set(nonce, 0);\n  buf"
    ".set(bytes, nonce.length);\n  const diges"
    "t = sha1(buf);\n  const msg = new Uint8Ar"
    "ray(1 + digest.length);\n  msg[0] = IN_AU"
    "TH;\n  msg.set(digest, 1);\n  if (st.ws &&"
    " st.ws.readyState === 1) st.ws.send(msg)"
    ";\n}\n\nfunction askForPassword(nonce, wron"
    "g) {\n  ui.ask.classList.add(\"on\");\n  ui."
    "askwhy.textContent = wrong\n    ? \"That w"
    "as not it. Try again.\"\n    : \"Set in SYS"
    "TEM.CFG, section [phone].\";\n  ui.askwhy."
    "classList.toggle(\"bad\", !!wrong);\n  ui.a"
    "skpw.value = \"\";\n  setTimeout(() => ui.a"
    "skpw.focus(), 50);\n  st.pendingNonce = n"
    "once;\n}\n\nui.askform.addEventListener(\"su"
    "bmit\", (e) => {\n  e.preventDefault();\n  "
    "const pw = ui.askpw.value;\n  if (!pw) re"
    "turn;\n  rememberPassword(pw);\n  ui.ask.c"
    "lassList.remove(\"on\");\n  if (st.pendingN"
    "once) {\n    answerChallenge(st.pendingNo"
    "nce, pw);\n    st.pendingNonce = null;\n  "
    "} else {\n    connect();\n  }\n});\n\nfunctio"
    "n connect() {\n  const url = (location.pr"
    "otocol === \"https:\" ? \"wss://\" : \"ws://\""
    ") +\n              location.host + \"/ws\";"
    "\n  const ws = new WebSocket(url);\n  ws.b"
    "inaryType = \"arraybuffer\";\n  st.ws = ws;"
    "\n\n  ws.onopen = () => {\n    if (ws !== s"
    "t.ws) { ws.close(); return; }\n    ui.dot"
    ".classList.add(\"on\");\n    ui.note.textCo"
    "ntent = location.host;\n    setBar(\"\");\n "
    "   ws.send(new Uint8Array([IN_HELLO]));\n"
    "  };\n  ws.onclose = (ev) => {\n    /*\n   "
    "  * Only from the socket that is current"
    ".  A page that opened two - and it\n     "
    "* could, see the visibility handler - ge"
    "ts the board's \"replaced\" for the\n     *"
    " one it abandoned, which is not news and"
    " must not be shown as though the\n     * "
    "live link had been taken away.  Caught e"
    "xactly that way: a freshly loaded\n     *"
    " page saying another device had the scre"
    "en while it was connected.\n     */\n    i"
    "f (ws !== st.ws) return;\n    ui.dot.clas"
    "sList.remove(\"on\");\n\n    /*\n     * The b"
    "oard allows one client: there is one scr"
    "een and one keyboard.  When\n     * a sec"
    "ond browser takes the link it says so in"
    " the close, and the one that\n     * lost"
    " it must NOT come straight back - two pa"
    "ges reconnecting at each\n     * other is"
    " a link that flaps about once a second a"
    "nd looks like a fault.\n     * Wait to be"
    " asked instead, and say so where it can "
    "be read without\n     * covering the pict"
    "ure that is still on the glass.\n     */\n"
    "    if (ev && ev.reason === \"replaced\") "
    "{\n      ui.note.textContent = \"screen ta"
    "ken\";\n      setBar(\"Another device has t"
    "his screen \342\200\224 tap here to take it back\""
    ",\n             false, () => { setBar(\"co"
    "nnecting\342\200\246\"); connect(); });\n      retu"
    "rn;\n    }\n    if (ev && ev.reason === \"b"
    "adpass\") {\n      ui.note.textContent = \""
    "locked\";\n      rememberPassword(\"\");\n   "
    "   setBar(\"Wrong password \342\200\224 tap here t"
    "o try again\", true, () => {\n        setB"
    "ar(\"connecting\342\200\246\");\n        connect();\n"
    "      });\n      askForPassword(null, tru"
    "e);\n      return;\n    }\n\n    ui.note.tex"
    "tContent = \"reconnecting\342\200\246\";\n    setBar"
    "(\"The board is not answering \342\200\224 reconne"
    "cting\342\200\246\");\n    /*\n     * A second, not "
    "immediately.  A board that has just been"
    " reset refuses\n     * connections for a "
    "few seconds, and a page that retries as "
    "fast as it can\n     * is a page that spe"
    "nds that time producing errors.\n     */\n"
    "    setTimeout(connect, 1000);\n  };\n  ws"
    ".onerror = () => ws.close();\n  ws.onmess"
    "age = (ev) => {\n    if (ws !== st.ws) re"
    "turn;\n    onMessage(new DataView(ev.data"
    "));\n  };\n}\n\nfunction onMessage(v) {\n  if"
    " (v.byteLength < 1) return;\n  const op ="
    " v.getUint8(0);\n\n  if (op === OP_AUTH) {"
    "\n    /* The board has asked who this is,"
    " and will send nothing else until it is\n"
    "     * answered.  A password we already "
    "hold goes straight back; otherwise the\n "
    "    * person is asked, once, and the ans"
    "wer is kept for next time. */\n    const "
    "nonce = new Uint8Array(v.buffer, 1, v.by"
    "teLength - 1);\n    const pw = storedPass"
    "word();\n    if (pw) {\n      answerChalle"
    "nge(nonce, pw);\n    } else {\n      askFo"
    "rPassword(new Uint8Array(nonce), false);"
    "\n    }\n    return;\n  }\n\n  /* Anything el"
    "se means the board is talking, so it is "
    "satisfied. */\n  ui.ask.classList.remove("
    "\"on\");\n\n  if (op === OP_INFO) {\n    st.s"
    "urfW = v.getUint16(1, true);\n    st.surf"
    "H = v.getUint16(3, true);\n    const cols"
    " = v.getUint8(5), rows = v.getUint8(6);\n"
    "    st.cellW = v.getUint8(7) || 8;\n    s"
    "t.cellH = v.getUint8(8) || 16;\n    if (c"
    "ols && rows && (cols !== st.cols || rows"
    " !== st.rows)) {\n      st.cols = cols; s"
    "t.rows = rows; resizeText();\n    }\n    i"
    "f (st.surfW && st.surfH) resizePix(st.su"
    "rfW, st.surfH);\n    return;\n  }\n\n  if (o"
    "p === OP_ROW) {\n    const y = v.getUint8"
    "(1), n = v.getUint8(2);\n    if (y >= st."
    "rows) return;\n    for (let x = 0; x < n "
    "&& x < st.cols; x++) {\n      st.cells[y "
    "* st.cols + x] =\n        v.getUint8(3 + "
    "x * 2) | (v.getUint8(4 + x * 2) << 8);\n "
    "   }\n    schedulePaint([y]);\n    showTex"
    "t();\n    return;\n  }\n\n  if (op === OP_CU"
    "RSOR) {\n    const x = v.getUint8(1), y ="
    " v.getUint8(2);\n    const ch = v.getUint"
    "8(3), attr = v.getUint8(4), on = v.getUi"
    "nt8(5) !== 0;\n    const was = { x: st.cu"
    "r.x, y: st.cur.y };\n    if (y < st.rows "
    "&& x < st.cols) st.cells[y * st.cols + x"
    "] = ch | (attr << 8);\n    st.cur = { x, "
    "y, on };\n    schedulePaint([was.y, y]);\n"
    "    showText();\n    return;\n  }\n\n  if (o"
    "p === OP_RAW || op === OP_PACK || op ==="
    " OP_IDX) {\n    band(op, v, 1, v.byteLeng"
    "th);\n  }\n}\n\nfunction send(bytes) {\n  if "
    "(st.ws && st.ws.readyState === 1) st.ws."
    "send(new Uint8Array(bytes));\n}\n\n/* ---- "
    "keys -----------------------------------"
    "-------------------------- */\n\nfunction "
    "sendKey(kind, hid, unicode, mods) {\n  co"
    "nst m = (mods === undefined ? st.sticky "
    ": mods);\n  send([IN_KEY, kind, m, hid & "
    "255, hid >> 8, unicode & 255,\n        (u"
    "nicode >> 8) & 255, 0]);\n}\n\nfunction tap"
    "(hid) {\n  sendKey(1, hid, 0);\n  sendKey("
    "2, hid, 0);\n  clearSticky();\n}\n\nfunction"
    " clearSticky() {\n  if (!st.sticky) retur"
    "n;\n  st.sticky = 0;\n  for (const b of ui"
    ".keys.querySelectorAll(\"button.held\")) {"
    "\n    b.classList.remove(\"held\");\n  }\n}\n\n"
    "/*\n * The bar of keys a phone's own keyb"
    "oard does not have.\n *\n * Ctrl and Alt l"
    "atch rather than repeat: there is no way"
    " to hold one down and\n * press a letter "
    "on a touch screen, so a tap arms it for "
    "the next keystroke and\n * the keystroke "
    "clears it.  That is how every terminal a"
    "pplication on a phone\n * has to do it, a"
    "nd it is the reason Ctrl+C from here rea"
    "ches the shell at all.\n */\nconst KEYBAR "
    "= [\n  [\"Esc\", () => tap(K.esc)],\n  [\"Tab"
    "\", () => tap(K.tab)],\n  [\"Ctrl\", \"mod\", "
    "MOD.ctrl],\n  [\"Alt\", \"mod\", MOD.alt],\n  "
    "[\"\342\206\221\", () => tap(K.up)],\n  [\"\342\206\223\", () ="
    "> tap(K.down)],\n  [\"\342\206\220\", () => tap(K.le"
    "ft)],\n  [\"\342\206\222\", () => tap(K.right)],\n  ["
    "\"\342\217\216\", () => tap(K.enter)],\n  [\"\342\214\253\", ()"
    " => tap(K.back)],\n  [\"Home\", () => tap(K"
    ".home)],\n  [\"End\", () => tap(K.end)],\n  "
    "[\"PgUp\", () => tap(K.pgup)],\n  [\"PgDn\", "
    "() => tap(K.pgdn)],\n  [\"Del\", () => tap("
    "K.del)],\n  [\"F1\", () => tap(K.f1)], [\"F2"
    "\", () => tap(K.f2)], [\"F3\", () => tap(K."
    "f3)],\n  [\"F4\", () => tap(K.f4)], [\"F5\", "
    "() => tap(K.f5)], [\"F6\", () => tap(K.f6)"
    "],\n  [\"F7\", () => tap(K.f7)], [\"F8\", () "
    "=> tap(K.f8)], [\"F9\", () => tap(K.f9)],\n"
    "  [\"F10\", () => tap(K.f10)], [\"F11\", () "
    "=> tap(K.f11)], [\"F12\", () => tap(K.f12)"
    "],\n];\n\nfor (const item of KEYBAR) {\n  co"
    "nst b = document.createElement(\"button\")"
    ";\n  b.textContent = item[0];\n  if (item["
    "1] === \"mod\") {\n    const bit = item[2];"
    "\n    b.onclick = () => {\n      st.sticky"
    " ^= bit;\n      b.classList.toggle(\"held\""
    ", (st.sticky & bit) !== 0);\n    };\n  } e"
    "lse {\n    b.onclick = item[1];\n  }\n  ui."
    "keys.appendChild(b);\n}\n\n/* ---- the keyb"
    "oard the page carries itself -----------"
    "------------------- */\n\n/*\n * Drawn here"
    " rather than asked of the phone, because"
    " the phone says no.\n *\n * A browser rais"
    "es its keyboard for a field the person c"
    "an see and refuses it\n * for one parked "
    "off screen at zero opacity - and off scr"
    "een is the only place\n * such a field ca"
    "n be parked behind a full-screen canvas."
    "  Reported as \"the\n * keyboard is not th"
    "ere, only the one row with Esc and Tab\","
    " and it was exactly\n * that.  So these k"
    "eys are the page's own, and whether they"
    " appear is not an\n * opinion anything el"
    "se gets to have.  `abc` in the header st"
    "ill tries the\n * phone's, for whoever wa"
    "nts their own autocomplete and emoji.\n *"
    "\n * Each key is [label, shifted label, H"
    "ID usage].  The HID goes out beside the\n"
    " * character because this system's keyco"
    "des are USB usage ids and applications\n "
    "* read either - a shell wants the charac"
    "ter, DOOM wants the key.\n */\nconst KEYS "
    "= [\n  [[\"1\",\"!\",K[\"1\"]],[\"2\",\"@\",K[\"2\"]]"
    ",[\"3\",\"#\",K[\"3\"]],[\"4\",\"$\",K[\"4\"]],\n   ["
    "\"5\",\"%\",K[\"5\"]],[\"6\",\"^\",K[\"6\"]],[\"7\",\"&"
    "\",K[\"7\"]],[\"8\",\"*\",K[\"8\"]],\n   [\"9\",\"(\","
    "K[\"9\"]],[\"0\",\")\",K[\"0\"]]],\n  [[\"q\",\"Q\",K"
    ".q],[\"w\",\"W\",K.w],[\"e\",\"E\",K.e],[\"r\",\"R\""
    ",K.r],[\"t\",\"T\",K.t],\n   [\"y\",\"Y\",K.y],[\""
    "u\",\"U\",K.u],[\"i\",\"I\",K.i],[\"o\",\"O\",K.o],"
    "[\"p\",\"P\",K.p]],\n  [[\"a\",\"A\",K.a],[\"s\",\"S"
    "\",K.s],[\"d\",\"D\",K.d],[\"f\",\"F\",K.f],[\"g\","
    "\"G\",K.g],\n   [\"h\",\"H\",K.h],[\"j\",\"J\",K.j]"
    ",[\"k\",\"K\",K.k],[\"l\",\"L\",K.l]],\n  [[\"z\",\""
    "Z\",K.z],[\"x\",\"X\",K.x],[\"c\",\"C\",K.c],[\"v\""
    ",\"V\",K.v],[\"b\",\"B\",K.b],\n   [\"n\",\"N\",K.n"
    "],[\"m\",\"M\",K.m],\n   [\",\",\"<\",K.comma],[\""
    ".\",\">\",K.period]],\n  [[\"\\\\\",\"|\",K.backsl"
    "ash],[\";\",\":\",K.semicolon],[\"-\",\"_\",K.mi"
    "nus],\n   [\"/\",\"?\",K.slash],[\"=\",\"+\",K.eq"
    "ual],[\"'\",\"\\\"\",K.quote],\n   [\"[\",\"{\",K.l"
    "bracket],[\"]\",\"}\",K.rbracket]],\n];\n\nlet "
    "shifted = false;\n\nfunction keyButton(spe"
    "c) {\n  const b = document.createElement("
    "\"button\");\n  const paint = () => { b.tex"
    "tContent = shifted ? spec[1] : spec[0]; "
    "};\n  paint();\n  b._paint = paint;\n  b.ad"
    "dEventListener(\"pointerdown\", (e) => {\n "
    "   e.preventDefault();\n    const ch = sh"
    "ifted ? spec[1] : spec[0];\n    const mod"
    "s = st.sticky | (shifted ? MOD.shift : 0"
    ");\n    /*\n     * With Ctrl or Alt armed "
    "this is a chord and not a character: the"
    " shell\n     * wants Ctrl+C as a keystrok"
    "e with a keycode, not as the letter c.\n "
    "    */\n    const uni = (st.sticky & (MOD"
    ".ctrl | MOD.alt)) ? 0 : ch.codePointAt(0"
    ");\n    sendKey(1, spec[2], uni, mods);\n "
    "   sendKey(2, spec[2], 0, mods);\n    cle"
    "arSticky();\n    if (shifted) { shifted ="
    " false; repaintKeys(); }\n  });\n  return "
    "b;\n}\n\nfunction specialButton(label, cls,"
    " fn) {\n  const b = document.createElemen"
    "t(\"button\");\n  b.textContent = label;\n  "
    "if (cls) b.className = cls;\n  b.addEvent"
    "Listener(\"pointerdown\", (e) => { e.preve"
    "ntDefault(); fn(b); });\n  return b;\n}\n\nf"
    "unction repaintKeys() {\n  for (const b o"
    "f ui.kbd.querySelectorAll(\"button\")) {\n "
    "   if (b._paint) b._paint();\n  }\n  const"
    " sh = ui.kbd.querySelector(\"button.shift"
    "\");\n  if (sh) sh.classList.toggle(\"held\""
    ", shifted);\n}\n\nfunction buildKeyboard() "
    "{\n  for (let i = 0; i < KEYS.length; i++"
    ") {\n    const row = document.createEleme"
    "nt(\"div\");\n    row.className = \"row\";\n  "
    "  if (i === 3) {\n      const sh = specia"
    "lButton(\"\342\207\247\", \"mod shift\", () => {\n    "
    "    shifted = !shifted;\n        repaintK"
    "eys();\n      });\n      sh.classList.add("
    "\"shift\");\n      row.appendChild(sh);\n   "
    " }\n    for (const spec of KEYS[i]) row.a"
    "ppendChild(keyButton(spec));\n    if (i ="
    "== 2) {\n      row.appendChild(specialBut"
    "ton(\"\342\214\253\", \"mod\", () => tap(K.back)));\n "
    "   }\n    if (i === 3) {\n      row.append"
    "Child(specialButton(\"\342\217\216\", \"mod\", () => "
    "tap(K.enter)));\n    }\n    ui.kbd.appendC"
    "hild(row);\n  }\n\n  const last = document."
    "createElement(\"div\");\n  last.className ="
    " \"row\";\n  last.appendChild(specialButton"
    "(\"Esc\", \"mod\", () => tap(K.esc)));\n  las"
    "t.appendChild(specialButton(\"Tab\", \"mod\""
    ", () => tap(K.tab)));\n  /* Space carries"
    " its character as well as its usage id. "
    " The kernel maps a\n   * usage to a chara"
    "cter for a real USB keyboard, so this wo"
    "uld work either\n   * way - but a key tha"
    "t means a character and does not say so "
    "is a key that\n   * depends on somebody e"
    "lse's table staying right. */\n  last.app"
    "endChild(specialButton(\"space\", \"xwide\","
    " () => {\n    sendKey(1, K.space, 32, st."
    "sticky);\n    sendKey(2, K.space, 0, st.s"
    "ticky);\n    clearSticky();\n  }));\n  last"
    ".appendChild(specialButton(\"`\", \"mod\", ("
    ") => {\n    sendKey(1, K.grave, shifted ?"
    " 126 : 96, st.sticky);\n    sendKey(2, K."
    "grave, 0, st.sticky);\n    clearSticky();"
    "\n  }));\n  last.appendChild(specialButton"
    "(\"\342\214\253\", \"mod\", () => tap(K.back)));\n  ui"
    ".kbd.appendChild(last);\n}\n\nbuildKeyboard"
    "();\n\n/*\n * Up by default on anything wit"
    "h a finger, folded away on a desktop whe"
    "re a\n * real keyboard is already attache"
    "d and these keys are only lost screen.  "
    "A\n * phone that opens this page and sees"
    " no keys has, from where its owner is\n *"
    " standing, no keyboard at all - which is"
    " exactly how the first version was\n * re"
    "ported.\n */\nif (window.matchMedia && win"
    "dow.matchMedia(\"(pointer: coarse)\").matc"
    "hes) {\n  ui.kbd.classList.add(\"on\");\n  u"
    "i.kb.classList.add(\"held\");\n}\n\nui.kb.onc"
    "lick = () => {\n  ui.kbd.classList.toggle"
    "(\"on\");\n  ui.kb.classList.toggle(\"held\","
    " ui.kbd.classList.contains(\"on\"));\n};\n\n/"
    "* The phone's own, for whoever wants it."
    "  It may or may not appear - that is\n * "
    "the browser's decision and the reason th"
    "e keys above exist. */\nui.native.onclick"
    " = () => {\n  ui.sink.value = \"\";\n  ui.si"
    "nk.focus();\n};\n\n/*\n * A phone's keyboard"
    " reports characters, not keys.  Two path"
    "s, and both are\n * needed: `keydown` car"
    "ries the named keys on anything with a r"
    "eal keyboard and\n * often nothing useful"
    " on a touch one, while the hidden textar"
    "ea's `input`\n * event carries what was a"
    "ctually composed - including anything pa"
    "st ASCII,\n * which has no HID usage to b"
    "e named by.\n */\nconst BY_CODE = {\n  Esca"
    "pe: K.esc, Tab: K.tab, Enter: K.enter, B"
    "ackspace: K.back,\n  ArrowUp: K.up, Arrow"
    "Down: K.down, ArrowLeft: K.left, ArrowRi"
    "ght: K.right,\n  Home: K.home, End: K.end"
    ", PageUp: K.pgup, PageDown: K.pgdn, Dele"
    "te: K.del,\n  Space: K.space,\n};\nfor (let"
    " i = 1; i <= 12; i++) BY_CODE[\"F\" + i] ="
    " K[\"f\" + i];\n\nwindow.addEventListener(\"k"
    "eydown\", (e) => {\n  let mods = 0;\n  if ("
    "e.shiftKey) mods |= MOD.shift;\n  if (e.c"
    "trlKey) mods |= MOD.ctrl;\n  if (e.altKey"
    ") mods |= MOD.alt;\n  if (e.metaKey) mods"
    " |= MOD.gui;\n  mods |= st.sticky;\n\n  let"
    " hid = BY_CODE[e.code] || 0;\n  if (!hid "
    "&& /^Key[A-Z]$/.test(e.code)) hid = K[e."
    "code[3].toLowerCase()];\n  if (!hid && /^"
    "Digit[0-9]$/.test(e.code)) hid = K[e.cod"
    "e[5]];\n\n  const uni = (e.key && e.key.le"
    "ngth === 1) ? e.key.codePointAt(0) : 0;\n"
    "  if (!hid && !uni) return;\n\n  e.prevent"
    "Default();\n  sendKey(1, hid, (mods & MOD"
    ".ctrl) ? 0 : uni, mods);\n  sendKey(2, hi"
    "d, 0, mods);\n  clearSticky();\n});\n\nui.si"
    "nk.addEventListener(\"input\", () => {\n  c"
    "onst text = ui.sink.value;\n  ui.sink.val"
    "ue = \"\";\n  if (!text) return;\n  /*\n   * "
    "With Ctrl or Alt armed this is not text,"
    " it is a chord: the shell wants\n   * Ctr"
    "l+C as a keystroke with a keycode, not a"
    "s the letter c.\n   */\n  if (st.sticky &&"
    " text.length === 1) {\n    const c = text"
    ".toLowerCase();\n    const hid = K[c] || "
    "0;\n    if (hid) { tap(hid); return; }\n  "
    "}\n  send([IN_TEXT, ...new TextEncoder()."
    "encode(text)]);\n  clearSticky();\n});\n\nui"
    ".sink.addEventListener(\"beforeinput\", (e"
    ") => {\n  if (e.inputType === \"deleteCont"
    "entBackward\") { e.preventDefault(); tap("
    "K.back); }\n  if (e.inputType === \"insert"
    "LineBreak\") { e.preventDefault(); tap(K."
    "enter); }\n});\n\n/* ---- the pointer -----"
    "----------------------------------------"
    "--------- */\n\n/*\n * Where a touch lands,"
    " in the pixels the board measures a poin"
    "ter in.\n *\n * Two different surfaces and"
    " the board says which is live: an applic"
    "ation's,\n * whose size arrived with the "
    "picture, and the console's, which has no"
    " pixels\n * of its own and is measured in"
    " cells times the cell size the kernel dr"
    "aws\n * with.  Getting this wrong is the "
    "bug that put the cursor below the stylus"
    " on\n * the board's own touchscreen for a"
    " week, so it is computed from what the b"
    "oard\n * said rather than from what looks"
    " right.\n */\nfunction where(ev) {\n  const"
    " cv = (st.mode === \"pix\") ? ui.pix : ui."
    "text;\n  const r = cv.getBoundingClientRe"
    "ct();\n  if (r.width === 0 || r.height =="
    "= 0) return null;\n\n  const fx = (ev.clie"
    "ntX - r.left) / r.width;\n  const fy = (e"
    "v.clientY - r.top) / r.height;\n  if (fx "
    "< 0 || fx > 1 || fy < 0 || fy > 1) retur"
    "n null;\n\n  if (st.mode === \"pix\") {\n    "
    "return [Math.floor(fx * st.surfW), Math."
    "floor(fy * st.surfH)];\n  }\n  const col ="
    " Math.min(st.cols - 1, Math.floor(fx * s"
    "t.cols));\n  const row = Math.min(st.rows"
    " - 1, Math.floor(fy * st.rows));\n  retur"
    "n [col * st.cellW, row * st.cellH];\n}\n\nf"
    "unction sendPtr(kind, ev, buttons) {\n  c"
    "onst p = where(ev);\n  if (!p) return;\n  "
    "send([IN_PTR, kind, buttons, p[0] & 255,"
    " (p[0] >> 8) & 255,\n        p[1] & 255, "
    "(p[1] >> 8) & 255, 0]);\n}\n\nfor (const cv"
    " of [ui.text, ui.pix]) {\n  cv.addEventLi"
    "stener(\"pointerdown\", (e) => {\n    e.pre"
    "ventDefault();\n    cv.setPointerCapture("
    "e.pointerId);\n    st.ptrDown = true;\n   "
    " sendPtr(1, e, 1);\n  });\n  cv.addEventLi"
    "stener(\"pointermove\", (e) => {\n    if (!"
    "st.ptrDown) return;\n    e.preventDefault"
    "();\n    sendPtr(3, e, 1);\n  });\n  cv.add"
    "EventListener(\"pointerup\", (e) => {\n    "
    "if (!st.ptrDown) return;\n    e.preventDe"
    "fault();\n    st.ptrDown = false;\n    sen"
    "dPtr(2, e, 0);\n  });\n  cv.addEventListen"
    "er(\"pointercancel\", () => { st.ptrDown ="
    " false; });\n  cv.addEventListener(\"conte"
    "xtmenu\", (e) => e.preventDefault());\n}\n\n"
    "/*\n * Coming back from a locked screen. "
    " The socket is usually dead by then and "
    "the\n * browser has not noticed, so ask f"
    "or everything: the board answers 'H' by\n"
    " * resending the geometry and marking th"
    "e whole screen as owed.\n */\ndocument.add"
    "EventListener(\"visibilitychange\", () => "
    "{\n  if (document.visibilityState !== \"vi"
    "sible\") return;\n  /*\n   * CLOSING or CLO"
    "SED, not \"anything but OPEN\".  A socket "
    "still CONNECTING is\n   * one that has no"
    "t failed yet, and opening a second besid"
    "e it makes the board\n   * - which allows"
    " one client - throw the first away and r"
    "eport it, which is a\n   * page telling i"
    "ts owner that somebody took the screen f"
    "rom them one second\n   * after they load"
    "ed it.\n   */\n  if (!st.ws || st.ws.ready"
    "State >= 2) { connect(); return; }\n  if "
    "(st.ws.readyState === 1) send([IN_HELLO]"
    ");\n});\n\nresizeText();\nsetBar(\"connecting"
    "\342\200\246\");\nconnect();\n</script>\n";

#endif /* AG_PHONE_PAGE_H */
